'use strict';
/* Sedra POS V5 — standalone offline cashier, integer piastres, fractional grams to 0.01g. */
const DB_NAME='SedraCashierV5_20261108_FINAL';
const STORES=['products','customers','invoices','items','ledger','cash','stock','returns','closings','settings','audit','historical','purchases','payables'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let db,cart=new Map(),currentPage='sell',adminSession=false,saving=false,scannerStream=null,scannerTimer=null,modalCancel=null,selectedCustomerId=null,stockOnly=false,pendingScan=null,lastScanCode='',lastScanAt=0,scanAbsentFrames=0;
const now=()=>new Date().toISOString();
function day(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function uid(prefix='ID'){return prefix+'-'+(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2))}
function num(x){let v=String(x??'').replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/،/g,'.').trim();return v===''?NaN:Number(v)}
function cents(x){return Math.round(x*100)}
function money(c){return (c/100).toLocaleString('en-EG',{minimumFractionDigits:2,maximumFractionDigits:2})+' ج'}
function fmt(x){return Number(x).toLocaleString('en-EG',{maximumFractionDigits:3})}
const norm=x=>String(x??'').trim().toLocaleLowerCase().replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/\s+/g,' ');
const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const dateShow=x=>new Date(x).toLocaleString('ar-EG',{dateStyle:'medium',timeStyle:'short'});
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),3000)}
function req(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function done(t){return new Promise((resolve,reject)=>{t.oncomplete=()=>resolve();t.onabort=()=>reject(t.error||Error('transaction aborted'));t.onerror=()=>reject(t.error||Error('transaction error'))})}
function ensureStores(d){for(const s of STORES)if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:s==='closings'?'dateKey':s==='settings'?'key':'id'})}
function idbOpen(version=null){return new Promise((resolve,reject)=>{let r;try{r=version==null?indexedDB.open(DB_NAME):indexedDB.open(DB_NAME,version)}catch(e){reject(e);return}r.onupgradeneeded=()=>ensureStores(r.result);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error||Error('IndexedDB open failed'));r.onblocked=()=>reject(Object.assign(Error('قاعدة البيانات مفتوحة في نسخة أخرى من التطبيق. اقفل كل نوافذ كاشير سدرة وافتحه من جديد.'),{name:'BlockedError'}))})}
async function open(){if(!('indexedDB' in globalThis))throw Object.assign(Error('IndexedDB غير متاح في هذا المتصفح أو وضع التصفح الحالي.'),{name:'IndexedDBUnavailable'});let d=await idbOpen();const missing=STORES.filter(s=>!d.objectStoreNames.contains(s));if(!missing.length){d.onversionchange=()=>d.close();return d}const nextVersion=Math.max(1,Number(d.version||1)+1);d.close();d=await idbOpen(nextVersion);d.onversionchange=()=>d.close();return d}
async function all(s){return req(db.transaction(s,'readonly').objectStore(s).getAll())}
async function one(s,id){return req(db.transaction(s,'readonly').objectStore(s).get(id))}
async function put(s,obj){const tx=db.transaction(s,'readwrite');tx.objectStore(s).put(obj);await done(tx);return obj}
async function setting(k,def=null){return (await one('settings',k))?.value??def}
async function saveSetting(k,value){await put('settings',{key:k,value})}
const weightUnits=new Set(['كيلو','كيلوجرام','كجم','kg','جرام','g','وزن']);
function isWeight(p){return p.kind==='weight'||weightUnits.has(norm(p.unit))}
function normalizeProduct(p){const weighted=isWeight(p);return {...p,priceC:Number.isInteger(p.priceC)?p.priceC:cents(Number(p.price)||0),kind:weighted?'weight':'count',unit:weighted?'كيلو':p.unit||'قطعة',stockInitialized:p.stockInitialized!==false,stockQty:Number.isFinite(Number(p.stockQty))?Number(p.stockQty):0,stockStatus:p.stockStatus||'unverified',lowStockBase:Number.isFinite(p.lowStockBase)?p.lowStockBase:(weighted?500:5),packages:Array.isArray(p.packages)?p.packages:[],active:p.active!==false,barcode:String(p.barcode||''),code:String(p.code||p.id)};}
async function seed(){if(await one('settings','initialized'))return;const ps=(window.SEED_PRODUCTS||[]).map(normalizeProduct);const at=now(),tx=db.transaction(['products','settings','stock','audit'],'readwrite');for(const p of ps){tx.objectStore('products').put(p);if(p.active)tx.objectStore('stock').add({id:uid('ST'),productId:p.id,qtyBase:p.stockQty,actual:p.stockQty,previous:null,type:'opening',reference:'Jard Sedra '+(p.importedAt||'2026-11-08'),createdAt:at,dateKey:day()})}tx.objectStore('settings').put({key:'initialized',value:at});tx.objectStore('settings').put({key:'openingSource',value:'جرد سدرة - 2026-11-08 - نقطة بداية دون خصم المبيعات القديمة'});tx.objectStore('audit').add({id:uid('AU'),action:'initial_import',reference:'Jard Sedra 2026-11-08',count:ps.length,actor:'system',createdAt:at});await done(tx)}
async function persistence(){try{await navigator.storage?.persist?.()}catch{}}
function modal(title,html,onCancel=null){modalCancel=onCancel;$('#sheetTitle').textContent=title;$('#sheetBody').innerHTML=html;$('#overlay').hidden=false}
function closeModal(){stopScanner();$('#overlay').hidden=true;const f=modalCancel;modalCancel=null;if(f)f()}
$('#closeSheet').onclick=closeModal;$('#overlay').onclick=e=>{if(e.target===$('#overlay'))closeModal()};
const field=(id,label,placeholder='',type='text',value='')=>`<label class="form-label" for="${id}">${esc(label)}</label><input class="field" id="${id}" type="${type}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${type==='number'?'inputmode="decimal" step="any"':''}>`;
const options=(rows,selected='')=>rows.map(([v,label])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`).join('');
const currencyNumber=c=>Number((c/100).toFixed(2));
async function ensureAdmin(){if(adminSession)return true;return new Promise(async resolve=>{let settled=false;const finish=ok=>{if(settled)return;settled=true;modalCancel=null;closeModal();resolve(ok)};const cancel=()=>{if(!settled){settled=true;resolve(false)}};let stored=await setting('adminPin');if(!stored){modal('تأسيس رقم الإدارة',`<p class="help">اختار PIN من 4 أرقام على الأقل. احتفظ به؛ لا يوجد استرجاع تلقائي.</p>${field('pinA','PIN جديد','','password')}${field('pinB','تأكيد PIN','','password')}<button class="btn primary block" id="savePin">حفظ PIN</button>`,cancel);$('#savePin').onclick=async()=>{let a=$('#pinA').value,b=$('#pinB').value;if(!/^\d{4,}$/.test(a)||a!==b)return toast('PIN غير صالح أو غير متطابق');await saveSetting('adminPin',await sha(a));adminSession=true;finish(true)}}else{modal('صلاحية الإدارة',`${field('pinLogin','رقم الإدارة','','password')}<button class="btn primary block" id="checkPin">دخول</button>`,cancel);$('#checkPin').onclick=async()=>{if(await sha($('#pinLogin').value)!==stored)return toast('PIN غير صحيح');adminSession=true;finish(true)}}})}
async function sha(x){const bytes=new TextEncoder().encode(x);const h=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function closedToday(){return !!(await one('closings',day()))}
async function requireOpenDay(){if(await closedToday()){toast('اليوم مقفول. افتحه من الإدارة إذا كان هناك تصحيح.');return false}return true}
function switchPage(page){currentPage=page;$$('.page').forEach(e=>e.classList.toggle('active',e.id===page));$$('.nav').forEach(e=>e.classList.toggle('active',e.dataset.page===page));if(page==='invoices')renderInvoices();if(page==='credit')renderCustomers();if(page==='products')renderProducts();if(page==='more')renderMore();window.scrollTo(0,0)}
$$('.nav').forEach(b=>b.onclick=()=>switchPage(b.dataset.page));
function displayStock(p){if(!p.stockInitialized)return 'غير مثبت';const q=Number(p.stockQty||0),shown=isWeight(p)?fmt(q/1000)+' كجم':fmt(q)+' '+p.unit;return (p.stockStatus==='unverified'?'غير مجرود · ':'')+shown;}
function displayQty(p,qty){return isWeight(p)?`${fmt(qty/1000)} كجم`:`${fmt(qty)} ${p.unit}`}
const lineC=(p,qty,entry=null)=>{const rate=Number.isInteger(entry?.overridePriceC)?entry.overridePriceC:p.priceC;return entry?.mode==='money'&&Number.isInteger(entry.amountC)?entry.amountC:(isWeight(p)?Math.round(rate*qty/1000):rate*qty)};
const cartTotal=()=>[...cart.values()].reduce((s,x)=>s+lineC(x.p,x.qty,x),0);
function cartValid(){return cart.size>0&&[...cart.values()].every(x=>!x.invalid&&Number.isFinite(x.qty)&&x.qty>0&&(!isWeight(x.p)?Number.isInteger(x.qty):true)&&Number.isInteger(x.p.priceC)&&x.p.priceC>0&&Number.isInteger(lineC(x.p,x.qty,x))&&lineC(x.p,x.qty,x)>0)}
async function productSearch(q,limit=80){const v=norm(q);return (await all('products')).filter(x=>x.active!==false&&(!v||norm(x.name).includes(v)||norm(x.id).includes(v)||norm(x.code).includes(v)||norm(x.barcode).includes(v))).sort((a,b)=>a.name.localeCompare(b.name,'ar')).slice(0,limit)}
async function searchRender(){const v=$('#searchInput').value.trim(),box=$('#searchResults');if(!v){box.innerHTML='';return}const ps=await productSearch(v);if($('#searchInput').value.trim()!==v)return;box.innerHTML=ps.length?ps.slice(0,12).map(p=>`<div class="result"><div class="grow"><b>${esc(p.name)}</b><small>${esc(p.id)} · ${money(p.priceC)} / ${esc(isWeight(p)?'كيلو':p.unit)}</small></div><button class="add-btn" data-add="${esc(p.id)}">+</button></div>`).join(''):'<div class="blank">الصنف غير موجود. تقدر تضيفه في «الأصناف».</div>';box.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addProductToCart(b.dataset.add))}
$('#searchInput').addEventListener('input',searchRender);
$('#searchInput').addEventListener('keydown',async e=>{if(e.key!=='Enter')return;const v=e.target.value.trim();const p=(await productSearch(v)).find(p=>p.id.toLowerCase()===v.toLowerCase()||p.barcode===v);if(p){e.preventDefault();addProductToCart(p.id)}});
async function addProductToCart(id){const p=await one('products',id);if(!p||!p.active)return toast('الصنف غير متاح للبيع؛ راجعه من الأصناف');if(!(p.priceC>0))return toast('سعر البيع غير محدد');const entry=cart.get(id)||{p,qty:0,unit:isWeight(p)?(p.preferredWeightUnit||'g'):'count',mode:'qty',amountC:null,invalid:false};entry.p=p;if(!isWeight(p)&&entry.mode==='qty')entry.qty+=1;else if(!isWeight(p)&&entry.mode==='money'){entry.qty+=1;entry.amountC=entry.qty*p.priceC;}cart.set(id,entry);$('#searchInput').value='';$('#searchResults').innerHTML='';renderCart();if(isWeight(p)&&entry.qty===0)setTimeout(()=>{const el=document.querySelector(`[data-weight="${CSS.escape(id)}"]`);if(el)el.focus()},0)}
function renderCart(){const box=$('#cartItems');$('#cartCount').textContent=cart.size+' أصناف';$('#cartTotal').textContent=money(cartTotal());if(!cart.size){box.innerHTML='<div class="blank">اختار أول صنف عشان تبدأ الفاتورة</div>';return}box.innerHTML=[...cart.values()].map(x=>{const p=x.p,w=isWeight(p),qShown=x.unit==='kg'?x.qty/1000:x.qty;return `<div class="cart-line" data-cartline="${esc(p.id)}"><div class="item-head"><div><div class="item-name">${esc(p.name)}</div><small>${money(p.priceC)} / ${esc(w?'كيلو':p.unit)} · الرصيد ${esc(displayStock(p))}</small></div><b>${money(lineC(p,x.qty,x))}</b></div><div class="mode-controls"><button class="btn ${x.mode==='qty'?'primary':'outline'}" data-mode="qty" data-id="${esc(p.id)}">بالكمية</button><button class="btn ${x.mode==='money'?'primary':'outline'}" data-mode="money" data-id="${esc(p.id)}">بالمبلغ (ج)</button></div>${x.mode==='money'?`<div class="money-row"><label class="money-label">العميل طلب بكام؟</label><input class="unit-input" data-money="${esc(p.id)}" inputmode="decimal" type="number" step="0.01" min="0" value="${Number.isInteger(x.amountC)&&x.amountC>0?currencyNumber(x.amountC):''}" placeholder="المبلغ بالجنيه" /></div><div class="status-line" data-amount-info="${esc(p.id)}">${w?`الوزن المحسوب ${fmt(x.qty)} جرام`:`الكمية المحسوبة ${fmt(x.qty)} ${esc(p.unit)}`}</div>${x.invalid?'<div class="amount-error">المبلغ لا يمثل كمية صحيحة من الصنف؛ راجع الرقم.</div>':''}`:`<div class="qty-row"><div class="qty-tools">${w?`<input class="unit-input" type="number" step="any" min="0" inputmode="decimal" data-weight="${esc(p.id)}" placeholder="الوزن" value="${x.qty?fmt(qShown):''}"><div class="weight-tabs"><button data-unit="g" data-id="${esc(p.id)}" class="${x.unit==='g'?'active':''}">جرام</button><button data-unit="kg" data-id="${esc(p.id)}" class="${x.unit==='kg'?'active':''}">كيلو</button></div>`:`<button class="round" data-adjust="-1" data-id="${esc(p.id)}">−</button><span class="count-value">${fmt(x.qty)}</span><button class="round" data-adjust="1" data-id="${esc(p.id)}">+</button><small>${esc(p.unit)}</small>`}</div><button class="remove" data-remove="${esc(p.id)}" title="حذف الصنف">✕</button></div>${w&&x.qty===0?'<div class="input-note">اكتب الوزن قبل حفظ الفاتورة</div>':''}`}<div class="status-line ${x.p.stockQty-x.qty<0?'redtxt':''}">${x.p.stockQty-x.qty<0?'⚠ الرصيد الدفتري بعد البيع: '+esc(displayQty(x.p,x.p.stockQty-x.qty))+' — البيع مسموح':''}</div>${x.mode==='money'?`<button class="linkbtn" data-remove="${esc(p.id)}">حذف الصنف</button>`:''}</div>`}).join('');box.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{const x=cart.get(b.dataset.id);x.qty+=Number(b.dataset.adjust);if(x.qty<=0)cart.delete(b.dataset.id);renderCart()});box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.delete(b.dataset.remove);renderCart()});box.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{const x=cart.get(b.dataset.id);const mode=b.dataset.mode;if(x.mode===mode)return;x.mode=mode;x.invalid=false;if(mode==='money'){x.amountC=x.qty>0?lineC(x.p,x.qty):null}else{x.amountC=null}renderCart()});box.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{const x=cart.get(b.dataset.id);x.unit=b.dataset.unit;renderCart()});box.querySelectorAll('[data-weight]').forEach(inp=>inp.oninput=()=>{const x=cart.get(inp.dataset.weight),v=num(inp.value),grams=x.unit==='kg'?v*1000:v;x.qty=Number.isFinite(grams)&&grams>0?Math.round(grams*100)/100:0;x.invalid=false;const c=inp.closest('.cart-line');c.querySelector('.item-head>b').textContent=money(lineC(x.p,x.qty,x));$('#cartTotal').textContent=money(cartTotal())});box.querySelectorAll('[data-money]').forEach(inp=>inp.oninput=()=>{const x=cart.get(inp.dataset.money),v=num(inp.value),amt=cents(v),p=x.p;let valid=Number.isFinite(v)&&v>0&&Number.isSafeInteger(amt)&&amt>0&&p.priceC>0;if(valid){if(isWeight(p)){x.qty=Math.round(amt*1000/p.priceC*100)/100;valid=x.qty>0}else{const base=amt/p.priceC;valid=Number.isInteger(base)&&base>0;if(valid)x.qty=base;}}if(valid){x.amountC=amt;x.invalid=false}else{x.amountC=0;x.qty=0;x.invalid=true}const c=inp.closest('.cart-line');c.querySelector('.item-head>b').textContent=money(lineC(p,x.qty,x));c.querySelector('[data-amount-info]').textContent=valid?(isWeight(p)?'الوزن المحسوب: '+fmt(x.qty)+' جرام':'الكمية المحسوبة: '+fmt(x.qty)+' '+p.unit):'⚠ المبلغ مش مناسب للصنف أو غير صالح';c.querySelector('[data-amount-info]').classList.toggle('redtxt',!valid);$('#cartTotal').textContent=money(cartTotal())})}
$('#clearCart').onclick=()=>{if(cart.size&&confirm('تفريغ الفاتورة؟')){cart.clear();renderCart()}};
async function customers(){return (await all('customers')).sort((a,b)=>a.name.localeCompare(b.name,'ar'))}
async function addCustomer(name,phone=''){name=name.trim();if(name.length<2)throw Error('اسم العميل لازم يكون حرفين على الأقل');const existing=(await customers()).find(c=>norm(c.name)===norm(name));if(existing)return existing;const c={id:uid('CU'),name,phone:phone.trim(),createdAt:now()};await put('customers',c);return c}
function customerChooserHtml(id='saleCustomer'){return `<label class="form-label">بحث عن العميل</label><input class="field" id="${id}Search" placeholder="اكتب جزء من الاسم"><select id="${id}" class="field" size="5" style="min-height:130px"></select><details style="margin:8px 0"><summary class="help">+ إضافة عميل جديد</summary>${field(`${id}New`,'اسم العميل الجديد')}${field(`${id}Phone`,'رقم الهاتف (اختياري)','','tel')}<button class="btn secondary block" id="${id}Add">حفظ عميل جديد</button></details>`}
async function bindCustomerChooser(id){let list=await customers(),input=$(`#${id}Search`),sel=$(`#${id}`);const fill=()=>{let txt=norm(input.value);let filt=list.filter(c=>norm(c.name).includes(txt));sel.innerHTML=filt.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');sel.selectedIndex=filt.length?0:-1};input.oninput=fill;fill();$(`#${id}Add`).onclick=async()=>{try{const c=await addCustomer($(`#${id}New`).value,$(`#${id}Phone`).value);list=await customers();input.value=c.name;fill();sel.value=c.id;toast('تم إضافة العميل')}catch(e){toast(e.message)}}}
async function saveInvoice(paidC,customerId=null){if(saving)return;if(!await requireOpenDay())return;if(!cartValid())return toast('راجع الكميات والأوزان والمبالغ في الفاتورة');const total=cartTotal();if(!Number.isSafeInteger(paidC)||paidC<0||paidC>total)return toast('المبلغ المدفوع غير صالح');if(total-paidC>0&&!customerId)return toast('حدد عميل الآجل');const customer=customerId?await one('customers',customerId):null;if(total-paidC>0&&!customer)return toast('العميل غير موجود');saving=true;const id=uid('INV'),createdAt=now(),dk=day(),number='F-'+dk.replaceAll('-','')+'-'+id.slice(-8).toUpperCase();const items=[...cart.values()].map(x=>({id:uid('IT'),invoiceId:id,number,productId:x.p.id,productName:x.p.name,unit:x.p.unit,kind:x.p.kind,qtyBase:x.qty,priceC:x.p.priceC,totalC:lineC(x.p,x.qty,x),saleMode:x.mode,returnedQtyBase:0,returnedC:0,createdAt,dateKey:dk}));const invoice={id,number,createdAt,dateKey:dk,customerId:total-paidC>0?customerId:null,customerName:total-paidC>0?customer.name:'',totalC:total,cashC:paidC,creditC:total-paidC,returnC:0};const tx=db.transaction(['invoices','items','products','stock','ledger','cash','audit'],'readwrite');tx.objectStore('invoices').add(invoice);for(const it of items){tx.objectStore('items').add(it);const store=tx.objectStore('products');const r=store.get(it.productId);r.onsuccess=()=>{const p=r.result;if(p){p.stockQty=Math.round((Number(p.stockQty||0)-it.qtyBase)*100)/100;p.stockInitialized=true;store.put(p)}};tx.objectStore('stock').add({id:uid('ST'),productId:it.productId,qtyBase:-it.qtyBase,type:'sale',reference:number,createdAt,dateKey:dk})}if(paidC>0)tx.objectStore('cash').add({id:uid('CA'),amountC:paidC,type:'sale',reference:number,createdAt,dateKey:dk});if(total-paidC>0)tx.objectStore('ledger').add({id:uid('LE'),customerId,amountC:total-paidC,type:'invoice_credit',reference:number,invoiceId:id,createdAt,dateKey:dk});tx.objectStore('audit').add({id:uid('AU'),action:'sale',reference:number,actor:'cashier',createdAt});try{await done(tx);cart.clear();renderCart();closeModal();toast('تم حفظ الفاتورة '+number);refreshSaleWarnings();if(currentPage==='invoices')renderInvoices();return invoice}catch(e){console.error(e);toast('فشل الحفظ. لم يتم اعتماد الفاتورة.');throw e}finally{saving=false}}
$('#payCash').onclick=async()=>{if(!cartValid())return toast('أضف الأصناف واكتب الأوزان أولًا');if(!await requireOpenDay())return;const total=cartTotal();modal('دفع كاش كامل',`<div class="stat"><small>إجمالي الفاتورة</small><b>${money(total)}</b></div>${field('tender','المبلغ المستلم من العميل (اختياري)',String(currencyNumber(total)),'number',currencyNumber(total))}<div class="list-card" id="changeBox">الباقي للعميل: 0.00 ج</div><button class="btn primary block spaced" id="confirmCash">حفظ الفاتورة — كاش</button>`);function calc(){let tender=num($('#tender').value);$('#changeBox').textContent=Number.isFinite(tender)&&tender>=currencyNumber(total)?`الباقي للعميل: ${money(cents(tender)-total)}`:'المبلغ أقل من إجمالي الفاتورة'}$('#tender').oninput=calc;$('#confirmCash').onclick=async()=>{const tender=num($('#tender').value);if(!Number.isFinite(tender)||cents(tender)<total)return toast('المدفوع أقل من الإجمالي؛ استخدم آجل / جزئي');$('#confirmCash').disabled=true;try{await saveInvoice(total)}catch{$('#confirmCash')?.removeAttribute('disabled')}}};
$('#payMixed').onclick=async()=>{if(!cartValid())return toast('أضف الأصناف واكتب الأوزان أولًا');if(!await requireOpenDay())return;const total=cartTotal();modal('آجل أو دفع جزئي',`<div class="stat"><small>إجمالي الفاتورة</small><b>${money(total)}</b></div>${customerChooserHtml('saleCustomer')}<div class="list-card" id="customerBalanceWarn">اختار العميل لمراجعة رصيده السابق</div>${field('partialCash','المدفوع الآن كاش','0','number',0)}<div class="list-card" id="partialDue">الباقي آجل: ${money(total)}</div><button class="btn primary block spaced" id="confirmPartial">حفظ الفاتورة</button>`);await bindCustomerChooser('saleCustomer');const updateWarn=async()=>{const cid=$('#saleCustomer').value;if(!cid){$('#customerBalanceWarn').textContent='اختار عميل آجل';return}const old=balanceC(await ledgerFor(cid));const cash=num($('#partialCash').value),due=Number.isFinite(cash)?total-cents(cash):total;$('#customerBalanceWarn').innerHTML=`رصيد العميل السابق: <b>${money(old)}</b> · بعد الفاتورة: <b class="amber">${money(old+Math.max(0,due))}</b>`};$('#saleCustomer').onchange=updateWarn;$('#saleCustomerSearch').oninput=()=>setTimeout(updateWarn,30);updateWarn();$('#partialCash').oninput=()=>{let val=num($('#partialCash').value);$('#partialDue').textContent=(val>=0&&cents(val)<=total)?'الباقي آجل: '+money(total-cents(val)):'راجع المبلغ المدفوع';updateWarn()};$('#confirmPartial').onclick=async()=>{let cash=num($('#partialCash').value),customerId=$('#saleCustomer').value;if(!Number.isFinite(cash)||cash<0||cents(cash)>total)return toast('المبلغ المدفوع غير صالح');if(!customerId)return toast('اختار عميل من القائمة أو أضفه');$('#confirmPartial').disabled=true;try{await saveInvoice(cents(cash),customerId)}catch{$('#confirmPartial')?.removeAttribute('disabled')}}};
