async function renderCustomers(){let cs=await customers(),led=await all('ledger'),allInv=(await all('invoices')).filter(i=>i.creditC>0),returns=await all('returns'),txt=norm($('#customerSearch').value);const invoicesC=allInv.reduce((s,i)=>s+i.totalC,0),paidInitial=allInv.reduce((s,i)=>s+i.cashC,0),collected=led.filter(e=>e.type==='collection').reduce((s,e)=>s-e.amountC,0),returned=returns.filter(r=>allInv.some(i=>i.id===r.invoiceId)).reduce((s,r)=>s+r.amountC,0),balance=balanceC(led);$('#creditGlobalStats').innerHTML=`<div class="stat"><small>إجمالي قيمة فواتير الآجل</small><b>${money(invoicesC)}</b></div><div class="stat"><small>المدفوع (عند البيع + سداد لاحق)</small><b class="positive">${money(paidInitial+collected)}</b></div><div class="stat"><small>المتبقي على العملاء</small><b class="${balance>0?'amber':'positive'}">${money(balance)}</b></div><div class="stat"><small>مرتجعات فواتير الآجل</small><b>${money(returned)}</b></div>`;cs=cs.filter(c=>norm(c.name).includes(txt));$('#customerList').innerHTML=cs.length?cs.map(c=>{let balance=balanceC(led.filter(e=>e.customerId===c.id));return `<div class="list-card tap" data-customer="${esc(c.id)}"><div class="card-top"><strong>${esc(c.name)}</strong><b class="${balance>0?'amber':'positive'}">${money(balance)}</b></div><div class="card-meta">اضغط لفتح كشف الحساب الكامل</div></div>`}).join(''):'<div class="blank">مفيش عملاء مطابقين. أضف عميل جديد.</div>';$$('[data-customer]').forEach(el=>el.onclick=()=>renderCustomerDetail(el.dataset.customer));if(selectedCustomerId)await renderCustomerDetail(selectedCustomerId)}
