function openReceipt(cid){(async()=>{if(!await requireOpenDay())return;const c=await one('customers',cid),balance=balanceC(await ledgerFor(cid));if(balance<=0)return toast('لا توجد مديونية على هذا العميل');modal('تحصيل آجل',`<p class="help">العميل: <b>${esc(c.name)}</b></p><div class="stat"><small>إجمالي المطلوب</small><b>${money(balance)}</b></div>${field('receiptAmount','المبلغ اللي دفعه دلوقتي','0','number')}<div id="receiptRemaining" class="list-card">المتبقي: ${money(balance)}</div><button id="confirmReceipt" class="btn primary block spaced">تسجيل السداد في الحساب العام</button>`);$('#receiptAmount').oninput=()=>{const n=num($('#receiptAmount').value);$('#receiptRemaining').textContent=n>=0&&cents(n)<=balance?'المتبقي: '+money(balance-cents(n)):'مبلغ غير صالح'};$('#confirmReceipt').onclick=async()=>{const amount=num($('#receiptAmount').value);if(!(amount>0)||cents(amount)>balance)return toast('المبلغ أكبر من المديونية أو غير صالح');if(saving)return;saving=true;const at=now(),dk=day(),cashC=cents(amount),tx=db.transaction(['cash','ledger','audit'],'readwrite');tx.objectStore('cash').add({id:uid('CA'),amountC:cashC,type:'collection',reference:c.name,createdAt:at,dateKey:dk});tx.objectStore('ledger').add({id:uid('LE'),customerId:cid,amountC:-cashC,type:'collection',reference:'سداد كاش',createdAt:at,dateKey:dk});tx.objectStore('audit').add({id:uid('AU'),action:'credit_collection',reference:c.id,amountC:cashC,actor:'cashier',createdAt:at});try{await done(tx);closeModal();toast('تم تسجيل السداد مستقلًا عن الفواتير');await renderCustomers()}catch(e){console.error(e);toast('فشل حفظ السداد')}finally{saving=false}}})()}
