$('#refreshInvoices').onclick=renderInvoices;$('#invoiceFilter').onchange=renderInvoices;
async function invoiceDetails(id){const i=await one('invoices',id);if(!i)return;const items=(await all('items')).filter(x=>x.invoiceId===id),returns=(await all('returns')).filter(x=>x.invoiceId===id);modal('تفاصيل الفاتورة',`<div class="stat"><small>${esc(i.number)}</small><b>${money(i.totalC)}</b><div class="card-meta">${dateShow(i.createdAt)} · ${esc(i.customerName||'نقدي')}</div></div><div class="stats spaced"><div class="stat"><small>المدفوع وقت البيع</small><b>${money(i.cashC)}</b></div><div class="stat"><small>آجل مضاف للحساب</small><b>${money(i.creditC)}</b></div></div><p class="hint">أي سداد لاحق للآجل موجود في كشف حساب العميل، وليس هنا.</p><table class="item-table"><thead><tr><th>الصنف</th><th>الكمية</th><th>الإجمالي</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.productName)}</td><td>${esc(displayQty({kind:x.kind,unit:x.unit},x.qtyBase))}</td><td>${money(x.totalC)}</td></tr>`).join('')}</tbody></table>${returns.length?`<div class="divider"></div><b>مرتجعات الفاتورة</b><div class="ledger">${returns.map(r=>`<div class="ledger-row"><small>${dateShow(r.createdAt)} · ${esc(r.productName)}</small><b>${money(r.amountC)}</b></div>`).join('')}</div>`:''}<div class="divider"></div><button id="returnFromInvoice" class="btn danger block">مرتجع صنف — إدارة فقط</button>`);$('#returnFromInvoice').onclick=async()=>{closeModal();if(await ensureAdmin())openReturn(id)}}
async function openReturn(invoiceId){if(!await requireOpenDay())return;const i=await one('invoices',invoiceId),its=(await all('items')).filter(x=>x.invoiceId===invoiceId&&x.qtyBase-(x.returnedQtyBase||0)>.000001);if(!its.length)return toast('جميع الأصناف تم إرجاعها');modal('مرتجع / تصحيح',`<p class="help">المرتجع حركة مستقلة، ولا يمسح الفاتورة الأصلية.</p><label class="form-label">الصنف</label><select class="field" id="returnItem">${options(its.map(x=>[x.id,`${x.productName} · متاح ${displayQty({kind:x.kind,unit:x.unit},x.qtyBase-(x.returnedQtyBase||0))}`]))}</select>${field('returnQty','الكمية المرتجعة (للوزن: بالجرام)','1','number',1)}<p class="hint">للوزن ادخل الجرام، وللمعدود ادخل عدد الوحدات. يمكن إدخال جزء من جرام عند الحاجة.</p><div class="list-card" id="returnAmount">قيمة المرتجع: —</div><button class="btn danger block spaced" id="confirmReturn">اعتماد المرتجع</button>`);const calc=()=>{const x=its.find(x=>x.id===$('#returnItem').value),qty=num($('#returnQty').value),remain=x.qtyBase-(x.returnedQtyBase||0),isWhole=Math.abs(qty-remain)<.000001;const raw=Math.round(x.totalC*qty/x.qtyBase),price=isWhole?x.totalC-(x.returnedC||0):Math.min(raw,x.totalC-(x.returnedC||0));$('#returnAmount').textContent=Number.isFinite(qty)&&qty>0&&qty<=remain?'قيمة المرتجع: '+money(price):'راجع الكمية';return {x,qty,price,remain}};$('#returnItem').onchange=calc;$('#returnQty').oninput=calc;calc();$('#confirmReturn').onclick=async()=>{const {x,qty,price,remain}=calc();const valid=Number.isFinite(qty)&&qty>0&&qty<=remain+.000001&&(x.kind==='weight'?Math.abs(Math.round(qty*100)-qty*100)<0.000001:Number.isInteger(qty));if(!valid||price<0)return toast('الكمية المرتجعة غير صحيحة');if(saving)return;const cid=i.customerId,bal=cid?balanceC(await ledgerFor(cid)):0,creditBackC=cid?Math.min(Math.max(0,bal),price):0,cashBackC=price-creditBackC;if(!confirm(`قيمة المرتجع ${money(price)}. خصم من حساب العميل ${money(creditBackC)}، ورد نقدي ${money(cashBackC)}. تأكيد؟`))return;saving=true;const at=now(),dk=day(),tx=db.transaction(['items','products','stock','returns','cash','ledger','invoices','audit'],'readwrite');tx.objectStore('returns').add({id:uid('RT'),invoiceId,invoiceNumber:i.number,itemId:x.id,productId:x.productId,productName:x.productName,qtyBase:qty,amountC:price,creditC:creditBackC,cashC:cashBackC,createdAt:at,dateKey:dk});x.returnedQtyBase=Math.round(((x.returnedQtyBase||0)+qty)*100)/100;x.returnedC=(x.returnedC||0)+price;tx.objectStore('items').put(x);const ps=tx.objectStore('products'),r=ps.get(x.productId);r.onsuccess=()=>{const p=r.result;if(p){p.stockQty=Math.round((Number(p.stockQty||0)+qty)*100)/100;p.stockInitialized=true;ps.put(p)}};tx.objectStore('stock').add({id:uid('ST'),productId:x.productId,qtyBase:qty,type:'return',reference:i.number,createdAt:at,dateKey:dk});if(creditBackC)tx.objectStore('ledger').add({id:uid('LE'),customerId:cid,amountC:-creditBackC,type:'return_credit',reference:i.number,createdAt:at,dateKey:dk});if(cashBackC)tx.objectStore('cash').add({id:uid('CA'),amountC:-cashBackC,type:'return_refund',reference:i.number,createdAt:at,dateKey:dk});i.returnC=(i.returnC||0)+price;tx.objectStore('invoices').put(i);tx.objectStore('audit').add({id:uid('AU'),action:'return',reference:i.number,amountC:price,actor:'admin',createdAt:at});try{await done(tx);closeModal();toast('تم تسجيل المرتجع وتعديل المخزون');refreshSaleWarnings();if(currentPage==='invoices')renderInvoices();if(currentPage==='credit')renderCustomers()}catch(e){console.error(e);toast('فشل تسجيل المرتجع')}finally{saving=false}}}
// Product catalog
async function renderProducts(){const allp=(await all('products')).filter(p=>p.active!==false),v=norm($('#productSearch').value),low=allp.filter(p=>p.stockQty<=p.lowStockBase),negative=allp.filter(p=>p.stockQty<0),notVerified=allp.filter(p=>p.stockStatus==='unverified');$('#stockSummary').innerHTML=`<div class="stock-pill"><small>الأصناف</small><b>${allp.length}</b></div><div class="stock-pill stock-warning"><small>قرب النفاد</small><b>${low.length}</b></div><div class="stock-pill stock-negative"><small>بالسالب</small><b>${negative.length}</b></div>`;const ps=allp.filter(p=>(!stockOnly||p.stockQty<=p.lowStockBase)&&(!v||norm(p.name).includes(v)||norm(p.code).includes(v)||norm(p.barcode).includes(v))).sort((a,b)=>(a.stockQty<0?0:a.stockQty<=a.lowStockBase?1:2)-(b.stockQty<0?0:b.stockQty<=b.lowStockBase?1:2)||a.name.localeCompare(b.name,'ar')).slice(0,120);$('#productList').innerHTML=`<div class="hint">${stockOnly?'عرض النواقص فقط · ':''}${notVerified.length?'أصناف لم تعتمد بكشف جرد: '+notVerified.length+' · ':''}تم عرض ${ps.length} صنف</div>`+(ps.length?ps.map(p=>`<div class="list-card tap" data-product="${esc(p.id)}"><div class="card-top"><strong>${esc(p.name)}</strong><b>${money(p.priceC)}</b></div><div class="card-meta">${esc(p.code||p.id)} · ${esc(isWeight(p)?'سعر الكيلو':p.unit)} · <span class="stock-line ${p.stockQty<0?'dangerTxt':p.stockQty<=p.lowStockBase?'amber':''}">${esc(displayStock(p))}</span></div>${p.stockQty<0?'<span class="badge red">رصيد دفتري سالب — راجع الوارد</span>':p.stockQty<=p.lowStockBase?'<span class="badge amber">قرب النفاد</span>':''}</div>`).join(''):'<div class="blank">لا توجد نتائج</div>');$$('[data-product]').forEach(b=>b.onclick=()=>productDetails(b.dataset.product))}
$('#productSearch').oninput=renderProducts;
$('#addProduct').onclick=()=>showNewProduct();$('#quickReceive').onclick=()=>showReceive();$('#showAllProducts').onclick=()=>{stockOnly=false;$('#showAllProducts').className='btn small primary';$('#showLowProducts').className='btn small outline';renderProducts()};$('#showLowProducts').onclick=()=>{stockOnly=true;$('#showAllProducts').className='btn small outline';$('#showLowProducts').className='btn small primary';renderProducts()};
function showNewProduct(barcode=''){modal('إضافة صنف جديد',`${field('npName','اسم الصنف *')}${field('npPrice','سعر بيع الوحدة (للوزن سعر الكيلو)','0','number')}<label class="form-label">وحدة البيع</label><select id="npUnit" class="field">${options(['قطعة','زجاجة','كيس','علبة','عبوة','شرينك','كرتونة','كيلو','باكو','لفة','ربطة'].map(u=>[u,u]))}</select>${field('npBarcode','الباركود (اختياري)',barcode,'text',barcode)}<p class="hint">الكمية تبدأ من صفر ثم أضف الوارد أو تسوية الجرد. للموزون اختار كيلو وادخل الجرام أو الكيلو أثناء البيع.</p><button class="btn primary block" id="npSave">حفظ الصنف</button>`);$('#npSave').onclick=async()=>{const name=$('#npName').value.trim(),v=num($('#npPrice').value),unit=$('#npUnit').value,b=$('#npBarcode').value.trim();if(name.length<2||!Number.isFinite(v)||v<=0)return toast('راجع اسم وسعر البيع');const ps=await all('products');if(ps.some(p=>p.active!==false&&norm(p.name)===norm(name)&&p.unit===unit))return toast('الصنف موجود بنفس الاسم ووحدة البيع');if(b&&ps.some(p=>p.barcode===b))return toast('الباركود مستخدم');const nums=ps.map(x=>/^SC(\d+)$/.exec(x.code||'')).filter(Boolean).map(x=>+x[1]),code=b||'SC'+String(Math.max(0,...nums)+1).padStart(4,'0');const p={id:uid('P'),code,name,priceC:cents(v),unit,kind:unit==='كيلو'?'weight':'count',barcode:b,active:true,stockInitialized:true,stockStatus:'unverified',stockQty:0,lowStockBase:unit==='كيلو'?500:5,packages:[],createdAt:now(),source:'cashier-v5'};await put('products',p);closeModal();toast('تم إضافة الصنف برصيد دفتري صفر');renderProducts();refreshSaleWarnings()}}
async function productDetails(id){const p=await one('products',id);if(!p)return;const packs=(p.packages||[]).filter(x=>x.qtyBase>0).map(x=>`${esc(x.label)}: ${fmt(isWeight(p)?x.qtyBase/1000:x.qtyBase)} ${isWeight(p)?'كيلو':esc(p.unit)}${x.priceC!=null?' · شراء '+money(x.priceC):' · تكلفة غير مسجلة'}`).join('<div class="card-meta">')||'لم تسجل تعبئات شراء';modal('بيانات الصنف',`<div class="list-card"><strong>${esc(p.name)}</strong><div class="card-meta">${esc(p.code||p.id)} · باركود: ${esc(p.barcode||'غير مسجل')} · بيع: ${money(p.priceC)} / ${esc(p.unit)}</div><div class="card-meta">الرصيد: ${esc(displayStock(p))} · تنبيه عند ${esc(displayQty(p,p.lowStockBase))} أو أقل</div><div class="card-meta">${packs}</div></div><button class="btn primary block" id="pdReceive">+ تسجيل وارد للصنف</button><button class="btn secondary block spaced" id="pdAdd">إضافة للفاتورة</button><button class="btn outline block spaced" id="pdCount">تسوية جرد — إدارة</button><button class="btn outline block spaced" id="pdEdit">تعديل سعر / باركود / حد التنبيه — إدارة</button>`);$('#pdReceive').onclick=()=>showReceive(id);$('#pdAdd').onclick=()=>{closeModal();addProductToCart(id);switchPage('sell')};$('#pdEdit').onclick=async()=>{closeModal();if(await ensureAdmin())openProductAdmin(id)};$('#pdCount').onclick=async()=>{closeModal();if(await ensureAdmin())showCount(id)}}
async function openProductAdmin(id){const p=await one('products',id);modal('تعديل صنف — إدارة',`<p><b>${esc(p.name)}</b></p>${field('editName','اسم الصنف','','text',p.name)}${field('editPrice','سعر البيع','0','number',currencyNumber(p.priceC))}${field('editBarcode','الباركود','','text',p.barcode)}${field('editLimit',isWeight(p)?'حد التنبيه (جرام)':'حد التنبيه (وحدات)','','number',p.lowStockBase)}${isWeight(p)?`<label class="form-label">الوحدة الافتراضية للوزن</label><select id="editPreferred" class="field">${options([['g','جرام'],['kg','كيلو']],p.preferredWeightUnit||'g')}</select>`:''}<button id="saveProductAdmin" class="btn primary block">حفظ التعديل</button><p class="hint">الوحدة الأساسية للصنف لا تتغير بعد حفظ الفواتير؛ أنشئ صنفًا جديدًا إذا اختلفت طبيعة البيع.</p>`);$('#saveProductAdmin').onclick=async()=>{const value=num($('#editPrice').value),bar=$('#editBarcode').value.trim(),limit=num($('#editLimit').value),name=$('#editName').value.trim();if(!Number.isFinite(value)||value<=0||!name||!Number.isFinite(limit)||limit<0||(!isWeight(p)&&!Number.isInteger(limit)))return toast('راجع الاسم والسعر وحد التنبيه');if(bar&&(await all('products')).some(x=>x.id!==id&&x.barcode===bar))return toast('باركود مكرر');p.name=name;p.priceC=cents(value);p.barcode=bar;p.lowStockBase=limit;if(isWeight(p))p.preferredWeightUnit=$('#editPreferred').value;p.updatedAt=now();const tx=db.transaction(['products','audit'],'readwrite');tx.objectStore('products').put(p);tx.objectStore('audit').add({id:uid('AU'),action:'product_edit',reference:id,actor:'admin',createdAt:now()});await done(tx);closeModal();toast('تم تحديث الصنف');renderProducts();refreshSaleWarnings();searchRender()}}
// Admin: count, receive wholesale units, cash adjustments
$('#manageStock').onclick=async()=>{if(await ensureAdmin())showStockMenu()};$('#manageCash').onclick=async()=>{if(await ensureAdmin())showCashMove()};$('#adminPrice').onclick=async()=>{if(await ensureAdmin()){modal('تعديل الأسعار',`<p class="help">اختار صنف بالاسم لتعديل السعر أو باركوده.</p><input class="field" id="priceSearch" placeholder="بحث عن الصنف"><div id="priceResults" class="stack"></div>`);$('#priceSearch').oninput=async()=>{$('#priceResults').innerHTML=(await productSearch($('#priceSearch').value)).slice(0,12).map(p=>`<button class="btn secondary block" data-price="${esc(p.id)}">${esc(p.name)} · ${money(p.priceC)}</button>`).join('');$$('[data-price]').forEach(b=>b.onclick=()=>openProductAdmin(b.dataset.price))}}};$('#adminPin').onclick=()=>{adminSession=false;toast('تم قفل وضع الإدارة')};
async function productSelect(id){const list=(await all('products')).filter(p=>p.active!==false).sort((a,b)=>a.name.localeCompare(b.name,'ar'));return `<input class="field" id="${id}Search" placeholder="اكتب اسم الصنف للبحث"><select class="field" id="${id}" size="5" style="min-height:140px">${list.slice(0,30).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select>`}
async function bindProductSelector(id){const list=(await all('products')).filter(p=>p.active!==false);$(`#${id}Search`).oninput=()=>{const t=norm($(`#${id}Search`).value),shown=list.filter(p=>norm(p.name).includes(t)||norm(p.id).includes(t)).slice(0,30);$(`#${id}`).innerHTML=shown.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}}
function showStockMenu(){modal('مخزون وجرد',`<p class="help">الوارد الحقيقي يختلف عن التسوية. الوارد يعني بضاعة دخلت المحل، والتسوية تصحح رصيد الجرد الدفتري فقط.</p><button id="countNow" class="btn primary block">تسوية / جرد صنف</button><button id="receiveNow" class="btn secondary block spaced">تسجيل وارد (مسموح للكاشير)</button><button id="stockDiffNow" class="btn outline block spaced">مراجعة فروق الجرد</button><button id="reviewImportedNow" class="btn outline block spaced">مراجعة الأصناف غير المجرودة</button>`);$('#countNow').onclick=()=>showCount();$('#receiveNow').onclick=()=>showReceive();$('#stockDiffNow').onclick=showStockDiff;$('#reviewImportedNow').onclick=showImportedReview}
async function showStockDiff(){const events=(await all('stock')).filter(x=>x.type==='count').sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,80);const ps=await all('products'),map=new Map(ps.map(p=>[p.id,p]));modal('مراجعة الجرد والعجز',`<p class="help">الفروق تظهر فقط للأصناف التي كان لها رصيد سابق مثبت.</p><div class="stack">${events.length?events.map(e=>{const p=map.get(e.productId),diff=e.previous===null?null:e.actual-e.previous;return `<div class="list-card"><div class="card-top"><b>${esc(p?.name||e.productId)}</b><b class="${diff===null?'':diff<0?'dangerTxt':'positive'}">${diff===null?'جرد افتتاحي':(diff>0?'+':'')+fmt(diff)+' '+esc(isWeight(p||{unit:'قطعة'})?'جرام':p?.unit||'قطعة')}</b></div><div class="card-meta">${dateShow(e.createdAt)} · السابق ${e.previous===null?'غير مؤكد':fmt(e.previous)} · الفعلي ${fmt(e.actual)}</div></div>`}).join(''):'<div class="blank">لا يوجد سجل جرد بعد</div>'}</div>`)}
async function showCount(preselect=''){modal('تسوية الجرد الفعلي',`${await productSelect('countProduct')}${field('countAmount','الرصيد الفعلي: جرام للوزني أو عدد للصنف','0','number')}<p class="hint" id="countInfo"></p>${field('countReason','سبب التسوية (مطلوب)','مثال: خطأ في جرد البداية')}<button class="btn primary block" id="saveCount">اعتماد التسوية</button>`);await bindProductSelector('countProduct');if(preselect){const x=await one('products',preselect);$('#countProductSearch').value=x?.name||'';$('#countProductSearch').dispatchEvent(new Event('input'));$('#countProduct').value=preselect}const upd=async()=>{const p=await one('products',$('#countProduct').value);$('#countInfo').textContent=p?`الصنف: ${p.name} · ${isWeight(p)?'القياس بالجرام (1500 = 1.5 كجم)':'القياس بعدد '+p.unit} · الرصيد السابق ${displayStock(p)}`:''};$('#countProduct').onchange=upd;upd();$('#saveCount').onclick=async()=>{const p=await one('products',$('#countProduct').value),v=num($('#countAmount').value),reason=$('#countReason').value.trim();if(!p||!Number.isFinite(v)||v<0||(!isWeight(p)&&!Number.isInteger(v))||(isWeight(p)&&Math.abs(Math.round(v*100)-v*100)>0.000001)||!reason)return toast('راجع الصنف والكمية وسبب التسوية');const prev=Number(p.stockQty||0);p.stockQty=v;p.stockInitialized=true;p.stockStatus='verified';p.lastCountAt=now();const at=now(),tx=db.transaction(['products','stock','audit'],'readwrite');tx.objectStore('products').put(p);tx.objectStore('stock').add({id:uid('ST'),productId:p.id,qtyBase:v-prev,actual:v,previous:prev,type:'count',reference:reason,createdAt:at,dateKey:day()});tx.objectStore('audit').add({id:uid('AU'),action:'stock_adjustment',reference:p.id,previous:prev,actual:v,reason,actor:'admin',createdAt:at});await done(tx);closeModal();toast('تمت تسوية الجرد بدون تسجيل شراء وهمي');renderProducts();refreshSaleWarnings()}}
async function showReceive(preselect=''){if(!await requireOpenDay())return;modal('تسجيل وارد — يزيد المخزون',`${await productSelect('recProduct')}<label class="form-label">طريقة إدخال الكمية</label><select id="recWay" class="field"></select>${field('recAmount','عدد العبوات / الوحدات / الجرام / الكيلو','1','number',1)}${field('recCost','تكلفة الشراء لكل وحدة إدخال بالجنيه (اختياري)','','number')}${field('recSupplier','اسم المورد (اختياري)','','text')}${field('recNote','ملاحظة / رقم فاتورة المورد (اختياري)','','text')}<div class="list-card" id="receiveInfo">اختار الصنف لتحديد طريقة الوارد</div><button class="btn primary block spaced" id="saveReceive">تسجيل الوارد وإضافته للمخزون</button>`);await bindProductSelector('recProduct');if(preselect){const x=await one('products',preselect);$('#recProductSearch').value=x?.name||'';$('#recProductSearch').dispatchEvent(new Event('input'));$('#recProduct').value=preselect}const fill=async()=>{const p=await one('products',$('#recProduct').value);if(!p)return;const arr=(p.packages||[]).filter(x=>x.qtyBase>0);let opts=arr.map((a,j)=>[`pkg${j}`,`${a.label}: ${fmt(isWeight(p)?a.qtyBase/1000:a.qtyBase)} ${isWeight(p)?'كيلو':p.unit}`]);opts.push(...(isWeight(p)?[['gram','جرام مفرد'],['kilo','كيلو مفرد']]:[['piece','وحدة بيع مفردة']]));$('#recWay').innerHTML=options(opts);const first=arr[0];$('#recCost').value=first&&first.priceC!=null?currencyNumber(first.priceC):'';calc()};const calc=async()=>{const p=await one('products',$('#recProduct').value);if(!p)return;const way=$('#recWay').value,n=num($('#recAmount').value),a=Number(way.slice(3)),pkg=way.startsWith('pkg')?(p.packages||[])[a]:null,qty=n*(pkg?pkg.qtyBase:way==='kilo'?1000:1);$('#receiveInfo').innerHTML=Number.isFinite(qty)&&qty>0?`وارد: <b>${esc(displayQty(p,qty))}</b><br>الرصيد بعد الإضافة: <b>${esc(displayQty(p,Number(p.stockQty||0)+qty))}</b>`:'راجع الكمية'};$('#recProduct').onchange=fill;$('#recWay').onchange=async()=>{const p=await one('products',$('#recProduct').value);const v=$('#recWay').value,pack=v.startsWith('pkg')?(p.packages||[])[+v.slice(3)]:null;$('#recCost').value=pack?.priceC!=null?currencyNumber(pack.priceC):'';calc()};$('#recAmount').oninput=calc;await fill();$('#saveReceive').onclick=async()=>{const p=await one('products',$('#recProduct').value);if(!p)return toast('اختار صنفًا');const way=$('#recWay').value,n=num($('#recAmount').value),pack=way.startsWith('pkg')?(p.packages||[])[+way.slice(3)]:null,qtyBase=pack?pack.qtyBase:way==='kilo'?1000:1,qty=Math.round(n*qtyBase*100)/100,costRaw=$('#recCost').value.trim(),cost=costRaw===''?null:num(costRaw),supplier=$('#recSupplier').value.trim(),note=$('#recNote').value.trim();if(!(Number.isFinite(n)&&n>0&&Number.isFinite(qty)&&qty>0&&(isWeight(p)||Number.isInteger(qty))&&Number.isSafeInteger(Math.round(qty*100))))return toast('كمية الوارد غير صحيحة');if(cost!==null&&(!Number.isFinite(cost)||cost<0))return toast('تكلفة الشراء غير صحيحة');if(saving)return;saving=true;const previous=Number(p.stockQty||0),at=now(),dk=day(),costC=cost===null?null:cents(cost);p.stockQty=Math.round((previous+qty)*100)/100;p.stockInitialized=true;p.updatedAt=at;if(pack&&costC!==null){pack.priceC=costC;p.costUnknown=false}const tx=db.transaction(['products','stock','audit'],'readwrite');tx.objectStore('products').put(p);tx.objectStore('stock').add({id:uid('ST'),productId:p.id,qtyBase:qty,previous,actual:p.stockQty,type:'receive',packs:n,packSize:qtyBase,way,unitCostC:costC,supplier,reference:note||supplier||'وارد بضاعة',createdAt:at,dateKey:dk});tx.objectStore('audit').add({id:uid('AU'),action:'receive',reference:p.id,qtyBase:qty,costC,supplier,note,actor:'cashier',createdAt:at});try{await done(tx);closeModal();toast('تم تسجيل الوارد وتحديث المخزون');renderProducts();refreshSaleWarnings()}catch(e){console.error(e);toast('فشل تسجيل الوارد')}finally{saving=false}}}
async function showCashMove(){if(!await requireOpenDay())return;modal('حركة خزنة إدارية',`<label class="form-label">نوع الحركة</label><select id="cashType" class="field">${options([['withdraw','سحب شخصي (خارج)'],['supplier','سداد مورد (خارج)'],['expense','مصروف محل (خارج)'],['loss','فاقد / سرقة كاش (خارج)'],['deposit','إيداع نقدي (داخل)'],['other_in','دخول نقدي آخر']])}</select>${field('cashAmount','المبلغ','0','number')}${field('cashNote','البيان / السبب (مطلوب)')}<button id="saveCashMove" class="btn primary block">حفظ الحركة</button>`);$('#saveCashMove').onclick=async()=>{const amount=num($('#cashAmount').value),type=$('#cashType').value,note=$('#cashNote').value.trim();if(!(amount>0)||!note)return toast('اكتب مبلغ وسبب الحركة');const signs={withdraw:-1,supplier:-1,expense:-1,loss:-1,deposit:1,other_in:1},at=now();const tx=db.transaction(['cash','audit'],'readwrite');tx.objectStore('cash').add({id:uid('CA'),type,amountC:cents(amount)*signs[type],reference:note,dateKey:day(),createdAt:at});tx.objectStore('audit').add({id:uid('AU'),action:'cash_'+type,reference:note,actor:'admin',createdAt:at});await done(tx);closeModal();toast('تم تسجيل حركة الخزنة')}}
// Daily close & offline Excel reports
async function daily(dk){const [invoices,items,ledger,cash,returns]=await Promise.all(['invoices','items','ledger','cash','returns'].map(all));return{invoices:invoices.filter(x=>x.dateKey===dk),items:items.filter(x=>x.dateKey===dk),ledger:ledger.filter(x=>x.dateKey===dk),cash:cash.filter(x=>x.dateKey===dk),returns:returns.filter(x=>x.dateKey===dk)}}
function daySummary(d){const invTotal=d.invoices.reduce((s,x)=>s+x.totalC,0),saleCash=d.invoices.reduce((s,x)=>s+x.cashC,0),saleCredit=d.invoices.reduce((s,x)=>s+x.creditC,0),col=d.cash.filter(x=>x.type==='collection').reduce((s,x)=>s+x.amountC,0),cashReturns=d.cash.filter(x=>x.type==='return_refund').reduce((s,x)=>s+x.amountC,0),returns=d.returns.reduce((s,x)=>s+x.amountC,0),netCash=d.cash.reduce((s,x)=>s+x.amountC,0);return {invTotal,saleCash,saleCredit,col,cashReturns,returns,netCash,count:d.invoices.length}}
function prevDay(k){const dt=new Date(k+'T12:00:00');dt.setDate(dt.getDate()-1);return day(dt)}
async function renderMore(){const cl=await one('closings',day());$('#closeState').textContent=cl?'مغلق':'مفتوح';$('#closeDay').textContent=cl?'إغلاق اليوم (تم بالفعل)':'إغلاق اليوم وإصدار Excel';const hist=await all('historical'),total=hist.reduce((s,x)=>s+x.amountC,0),lastBackup=await setting('lastBackupAt');$('#historicalInfo').textContent=hist.length?`${hist.filter(x=>x.status!=='cancelled').length} قيد تاريخي · إجمالي ${money(hist.filter(x=>x.status!=='cancelled').reduce((s,x)=>s+x.amountC,0))}. لا تدخل ضمن مبيعات أو كاش اليوم ولا تخصم من المخزون.`:'لسه مفيش مبيعات قديمة متسجلة.';$('#historicalList').innerHTML=hist.filter(x=>x.status!=='cancelled').sort((a,b)=>b.dateKey.localeCompare(a.dateKey)).slice(0,10).map(x=>`<button class="btn secondary block" data-history="${esc(x.id)}">${esc(x.dateKey)} · ${money(x.amountC)} · ${x.type==='details'?'تفاصيل':'يومي'}</button>`).join('');$$('[data-history]').forEach(b=>b.onclick=()=>historicalDetails(b.dataset.history));const importState=$('#initialImportStatus');if(importState){const pcs=await all('products');importState.textContent=pcs.length?`البيانات موجودة بالفعل: ${pcs.length} صنف. استيراد الجرد الأولي مقفول لمنع تكرار البيانات.`:'مافيش بيانات أصناف مستوردة بعد؛ استخدم ملف الجرد الخاص.';$('#initialImport').disabled=pcs.length>0;}const hint=$('#backupReminder');if(hint)hint.textContent=lastBackup?'آخر تصدير نسخة احتياطية: '+dateShow(lastBackup):'لم يتم تصدير نسخة احتياطية من الجهاز ده حتى الآن.';}
$('#closeDay').onclick=async()=>{const dk=day(),existing=await one('closings',dk);if(existing){modal('اليوم مغلق',`<div class="stat"><small>فرق الخزنة</small><b>${money(existing.differenceC)}</b></div><button class="btn primary block spaced" id="reExport">تنزيل التقرير مرة أخرى</button><button class="btn danger block spaced" id="reopenDay">إعادة فتح اليوم — الإدارة</button>`);$('#reExport').onclick=async()=>{await exportDaily(dk,existing);toast('تم تنزيل التقرير')};$('#reopenDay').onclick=async()=>{closeModal();if(!await ensureAdmin())return;if(!confirm('فتح اليوم مجددًا؟ ستحتاج لإغلاقه من جديد بعد أي عمليات إضافية.'))return;const tx=db.transaction(['closings','audit'],'readwrite');tx.objectStore('closings').delete(dk);tx.objectStore('audit').add({id:uid('AU'),action:'reopen_day',reference:dk,actor:'admin',createdAt:now()});await done(tx);renderMore();toast('أعيد فتح اليوم')};return}const d=await daily(dk),s=daySummary(d),prev=await one('closings',prevDay(dk)),pref=prev?currencyNumber(prev.actualC):'';modal('إغلاق اليوم',`<div class="stats"><div class="stat"><small>مبيعات كاش</small><b>${money(s.saleCash)}</b></div><div class="stat"><small>مبيعات آجل</small><b>${money(s.saleCredit)}</b></div><div class="stat"><small>تحصيل آجل</small><b>${money(s.col)}</b></div><div class="stat"><small>فواتير</small><b>${s.count}</b></div></div><div class="list-card"><div class="split"><span>حركة الخزنة اليوم (شاملة المدفوعات والمصاريف)</span><b>${money(s.netCash)}</b></div></div>${field('openCash','كاش بداية اليوم الفعلي (إجباري)','0','number',pref)}${field('actualCash','الكاش الموجود فعليًا الآن (إجباري)','0','number')}<div id="closeCalc" class="list-card">أدخل الكاش لإظهار العجز أو الزيادة</div><button id="confirmClose" class="btn primary block spaced">تأكيد الإغلاق + تنزيل Excel</button><p class="hint">لو بداية اليوم غير معروفة لا تفترض صفر. اعمل عدّ فعلي وحددها بدقة قبل القفل.</p>`);const calc=()=>{const op=num($('#openCash').value),ac=num($('#actualCash').value),valid=Number.isFinite(op)&&op>=0&&Number.isFinite(ac)&&ac>=0;let expected=valid?cents(op)+s.netCash:0;$('#closeCalc').innerHTML=valid?`<div class="split"><span>المفروض في الخزنة</span><b>${money(expected)}</b></div><div class="split"><span>الفعلي</span><b>${money(cents(ac))}</b></div><div class="split"><span>الفرق</span><b class="${cents(ac)-expected<0?'dangerTxt':'positive'}">${money(cents(ac)-expected)}</b></div>`:'لازم تدخل رقم البداية والعدد الفعلي';return{op,ac,expected,valid}};$('#openCash').oninput=calc;$('#actualCash').oninput=calc;$('#confirmClose').onclick=async()=>{const {op,ac,expected,valid}=calc();if(!valid)return toast('لازم تدخل الكاش الصحيح');if(saving)return;saving=true;const closing={dateKey:dk,createdAt:now(),openingC:cents(op),actualC:cents(ac),expectedC:expected,differenceC:cents(ac)-expected,summary:s};try{const tx=db.transaction(['closings','audit'],'readwrite');tx.objectStore('closings').add(closing);tx.objectStore('audit').add({id:uid('AU'),action:'day_close',reference:dk,actor:'cashier',createdAt:now()});await done(tx);closeModal();await exportDaily(dk,closing);toast('تم إغلاق اليوم. احتفظ بالتقرير ونسخة Backup');renderMore()}catch(e){console.error(e);toast('تعذر الإغلاق')}finally{saving=false}}};
$('#exportDay').onclick=async()=>{await exportDaily(day());toast('تم تنزيل التقرير بدون إغلاق')};
async function exportDaily(dk,closing=null){const d=await daily(dk),s=daySummary(d),custMap=new Map((await customers()).map(c=>[c.id,c.name]));const summary=[['سدرة - تقرير اليومية',dk],['حالة اليوم',closing?'مغلق':'تقرير مؤقت'],['إجمالي الفواتير',currencyNumber(s.invTotal)],['مبيعات كاش عند البيع',currencyNumber(s.saleCash)],['مبيعات آجل مضافة',currencyNumber(s.saleCredit)],['تحصيل آجل نقدي',currencyNumber(s.col)],['مرتجعات بقيمتها',currencyNumber(s.returns)],['صافي حركة الخزنة',currencyNumber(s.netCash)],['عدد الفواتير',s.count],['كاش بداية اليوم',closing?currencyNumber(closing.openingC):'غير مدخل'],['المفروض في الخزنة',closing?currencyNumber(closing.expectedC):'غير مدخل'],['الكاش الفعلي',closing?currencyNumber(closing.actualC):'غير مدخل'],['الفرق',closing?currencyNumber(closing.differenceC):'غير محدد']];const inv=[['رقم الفاتورة','وقت البيع','العميل','الإجمالي','كاش عند الشراء','مضاف آجل','المرتجعات'],...d.invoices.map(x=>[x.number,x.createdAt,x.customerName,currencyNumber(x.totalC),currencyNumber(x.cashC),currencyNumber(x.creditC),currencyNumber(x.returnC||0)])];const items=[['الفاتورة','كود الصنف','الصنف','الوحدة','الكمية الأصلية بالوحدة الأساسية (جرام للوزن)','سعر الوحدة','قيمة السطر','المرتجع بالوحدة الأساسية'],...d.items.map(x=>[x.number,x.productId,x.productName,x.unit,x.qtyBase,currencyNumber(x.priceC),currencyNumber(x.totalC),x.returnedQtyBase])];const ledger=[['التاريخ','العميل','النوع','رقم الفاتورة أو البيان','تغيير المديونية'],...d.ledger.map(x=>[x.createdAt,custMap.get(x.customerId)||x.customerId,x.type,x.reference,currencyNumber(x.amountC)])];const cash=[['التاريخ','نوع الحركة','المرجع','الداخل/الخارج'],...d.cash.map(x=>[x.createdAt,x.type,x.reference,currencyNumber(x.amountC)])];const returns=[['التاريخ','رقم الفاتورة','الصنف','الكمية الأساسية','قيمة المرتجع','تخفيض مديونية','كاش مُعاد'],...d.returns.map(x=>[x.createdAt,x.invoiceNumber,x.productName,x.qtyBase,currencyNumber(x.amountC),currencyNumber(x.creditC),currencyNumber(x.cashC)])];downloadBlob(`Sedra_Daily_${dk}.xlsx`,makeXlsx([{name:'ملخص',rows:summary},{name:'الفواتير',rows:inv},{name:'الأصناف',rows:items},{name:'حسابات الآجل',rows:ledger},{name:'الخزنة',rows:cash},{name:'المرتجعات',rows:returns},{name:'مبيعات يدوية قديمة',rows:[['تاريخ قديم','القيمة','نوع التسجيل','تفاصيل','الحالة - لا تؤثر على المخزون'],...(await all('historical')).map(h=>[h.dateKey,currencyNumber(h.amountC),h.type,h.note,h.status||'active'])]}]))}
// Offline backup, restore. Backups are not uploaded to GitHub or any server.
async function backup(){const data={app:'sedra_pos_v5',schema:3,createdAt:now(),sourceDb:DB_NAME,sourceDeviceId:localDeviceId(),stores:{}};for(const s of STORES)data.stores[s]=await all(s);data.auditLatestAt=(data.stores.audit||[]).reduce((m,x)=>x.createdAt>m?x.createdAt:m,'');downloadBlob(`Sedra_V5_Backup_${day()}_${new Date().getHours()}-${new Date().getMinutes()}.json`,new Blob([JSON.stringify(data)],{type:'application/json;charset=utf-8'}));await saveSetting('lastBackupAt',now());return data}
$('#backup').onclick=async()=>{try{await backup();toast('تم تنزيل النسخة الاحتياطية. انقلها لمكان آمن.')}catch(e){console.error(e);toast('تعذر إنشاء النسخة الاحتياطية')}};
$('#restore').onclick=async()=>{if(!await ensureAdmin())return;$('#restoreFile').click()};
$('#restoreFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{const data=JSON.parse(await f.text());if(data?.app!=='sedra_pos_v5'||![2,3].includes(data.schema)||!data.stores||STORES.some(s=>!Array.isArray(data.stores[s])&&!(data.schema===2&&['purchases','payables'].includes(s))))throw Error('الملف مش Backup من كاشير سدرة V5');const ps=data.stores.products,ids=new Set(),bars=new Set();for(const p of ps){if(!p.id||ids.has(p.id))throw Error('أكواد أصناف مكررة');ids.add(p.id);if(p.barcode){if(bars.has(p.barcode))throw Error('باركود مكرر');bars.add(p.barcode)}}const localAudit=await all('audit'),localActivity=localAudit.filter(x=>x.action!=='initial_import'),incomingAudit=(data.stores.audit||[]).filter(x=>x.action!=='initial_import'),lastLocal=localActivity.reduce((m,x)=>x.createdAt>m?x.createdAt:m,''),lastIncoming=incomingAudit.reduce((m,x)=>x.createdAt>m?x.createdAt:m,'');if(localActivity.length&&lastLocal>=lastIncoming){alert('تم منع الاستيراد: الجهاز الحالي فيه حركات مساوية أو أحدث من النسخة المختارة. لازم تراجع أحدث Backup لتجنب ضياع فواتير.');return}if(!confirm(`استيراد نسخة بتاريخ ${dateShow(data.createdAt)}؟\nستحل محل بيانات كاشير V5 على هذا الجهاز فقط.\nلن تمس جرد سدرة ولا الكاشير القديم.\nسيتم تصدير نسخة أمان قبل الاستبدال.`))return;const typed=prompt('للتأكيد اكتب كلمة: استبدال');if(typed!=='استبدال')return;await backup();const tx=db.transaction(STORES,'readwrite');for(const s of STORES){const store=tx.objectStore(s);store.clear();for(const x of (data.stores[s]||[]))store.add(x)}await done(tx);toast('تم الاستيراد. افتح التطبيق بعد التحديث.');setTimeout(()=>location.reload(),800)}catch(err){console.error(err);toast(err.message||'ملف الاستعادة غير صالح')}};
function onlineInfo(){$('#onlineState').textContent=navigator.onLine?'● الجهاز متصل':'● بدون إنترنت';$('#dateText').textContent=new Date().toLocaleDateString('ar-EG',{day:'numeric',month:'short',year:'numeric'})}
window.addEventListener('online',onlineInfo);window.addEventListener('offline',onlineInfo);
async function init(){try{db=await open();await seed();await persistence();onlineInfo();renderCart();renderMore();refreshSaleWarnings();$('#searchInput').focus();await window.sedraUpgradeInit?.();/* Service Worker handled early by versioned pwa-updater.js; never tied to database startup. */}catch(e){console.error(e);const name=esc(e?.name||'Error'),msg=esc(e?.message||'تعذر فتح قاعدة البيانات');document.body.innerHTML=`<main dir="rtl" style="padding:30px;color:white;background:#111;font-family:Tahoma;min-height:100vh"><h2>تعذّر فتح قاعدة البيانات المحلية</h2><p style="color:#ffcc80"><b>${name}</b>: ${msg}</p><p>اقفل أي نسخة مفتوحة من كاشير سدرة، وافتح رابط GitHub Pages HTTPS في Chrome العادي ثم أعد المحاولة. لا تمسح بيانات الموقع قبل أخذ نسخة احتياطية إن كان عندك معاملات.</p></main>`}}

function localDeviceId(){const k='sedra_pos_v5_device_id';let v=localStorage.getItem(k);if(!v){v=uid('DEVICE');localStorage.setItem(k,v)}return v}
async function refreshSaleWarnings(){if(!db)return;const ps=(await all('products')).filter(p=>p.active!==false),bad=ps.filter(p=>p.stockQty<0),low=ps.filter(p=>p.stockQty>=0&&p.stockQty<=p.lowStockBase);const target=$('#sellStockAlerts');if(target)target.innerHTML=!ps.length?'⚠ ما فيش أصناف متسجلة. افتح «المزيد» واستورد ملف الجرد الخاص قبل البيع.':bad.length||low.length?`⚠ <b>${bad.length} صنف بالسالب</b> · ${low.length} صنف قرب النفاد. البيع مستمر، وسجل الوارد من «الأصناف».`:'✅ المخزون المسجل لا يحتوي حاليًا على أصناف أقل من حد التنبيه.'}
async function showImportedReview(){const ps=(await all('products')).filter(p=>p.stockStatus==='unverified'||p.active===false);modal('مراجعة الأصناف غير المحسومة',`<p class="help">الصنف الذي لم تُسجل له كمية في نسخة جرد سدرة محفوظ كمرجع، لكنه غير مفعل للبيع لتجنب تكرار السكر والشربات. لا يتم دمجه تلقائيًا.</p><div class="stack">${ps.map(p=>`<div class="list-card"><b>${esc(p.name)}</b><div class="card-meta">${esc(p.code)} · ${p.active?'مفعل':'موقوف للمراجعة'} · ${esc(displayStock(p))}</div><button class="btn small outline" data-review="${esc(p.id)}">تفعيل الصنف بعد التحقق</button></div>`).join('')||'<div class="blank">لا توجد أصناف معلقة.</div>'}</div>`);$$('[data-review]').forEach(b=>b.onclick=async()=>{const p=await one('products',b.dataset.review);const n=prompt(`تأكيد تفعيل «${p.name}»؟ اكتب رصيده الفعلي ${isWeight(p)?'بالجرام':'بعدد الوحدات'}.`);if(n===null)return;const q=num(n);if(!Number.isFinite(q)||q<0||(!isWeight(p)&&!Number.isInteger(q)))return toast('رصيد غير صحيح');if(!confirm('سيظهر الصنف للبيع مستقلًا عن أي صنف مشابه. هل أنت متأكد؟'))return;p.active=true;p.stockStatus='verified';const old=p.stockQty;p.stockQty=q;const at=now(),tx=db.transaction(['products','stock','audit'],'readwrite');tx.objectStore('products').put(p);tx.objectStore('stock').add({id:uid('ST'),productId:p.id,qtyBase:q-old,actual:q,previous:old,type:'count',reference:'manual data review',createdAt:at,dateKey:day()});tx.objectStore('audit').add({id:uid('AU'),action:'import_review_activate',reference:p.code,actor:'admin',createdAt:at});await done(tx);closeModal();toast('تم تفعيل الصنف');renderProducts();refreshSaleWarnings()})}
$('#addHistorical').onclick=()=>{modal('تسجيل مبيعات يدوية سابقة',`<p class="help">السجل ده للأرشفة فقط، ولا يخصم المخزون ولا يغير مبيعات أو كاش اليومية. لأن نقطة البداية هي الجرد المستورد بالفعل.</p>${field('hDate','تاريخ البيع','','date',day())}${field('hAmount','إجمالي المبيعات بالجنيه','0','number')}<label class="form-label">نوع البيان</label><select id="hType" class="field">${options([['summary','إجمالي يومي'],['details','تفاصيل مكتوبة يدويًا']])}</select><label class="form-label">تفاصيل الأصناف / ملاحظات (اختياري)</label><textarea id="hNote" class="field" rows="4" placeholder="مثال: بيع 2 كيس سكر و3 عبوات... أو أرقام الفواتير الورقية"></textarea><button id="saveHistorical" class="btn primary block">حفظ سجل تاريخي فقط</button>`);$('#saveHistorical').onclick=async()=>{const d=$('#hDate').value,amt=num($('#hAmount').value),type=$('#hType').value,note=$('#hNote').value.trim();if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||d>day()||!Number.isFinite(amt)||amt<=0)return toast('راجع التاريخ وإجمالي البيع: لازم يكون يوم سابق أو اليوم');const at=now(),tx=db.transaction(['historical','audit'],'readwrite');tx.objectStore('historical').add({id:uid('HS'),dateKey:d,amountC:cents(amt),type,note,createdAt:at,source:'manual_before_opening_stock',stockImpact:0});tx.objectStore('audit').add({id:uid('AU'),action:'historical_sale',reference:d,amountC:cents(amt),actor:'cashier',createdAt:at});await done(tx);closeModal();toast('تم حفظ المبيعات القديمة دون خصم المخزون');renderMore()}}


async function historicalDetails(id){const entry=await one('historical',id);if(!entry)return;modal('مبيعات سابقة — تعديل أو إلغاء',`<p class="help">لا تؤثر في المخزون أو الخزنة أو مبيعات اليومية.</p><p><b>${esc(entry.dateKey)}</b></p>${field('editOldAmount','القيمة المسجلة','','number',currencyNumber(entry.amountC))}<label class="form-label">التفاصيل</label><textarea id="editOldNotes" class="field" rows="4">${esc(entry.note||'')}</textarea><button id="saveOldHistory" class="btn primary block">تعديل السجل</button><button id="cancelOldHistory" class="btn danger block spaced">إلغاء السجل مع حفظ أثر الإلغاء</button>`);$('#saveOldHistory').onclick=async()=>{const v=num($('#editOldAmount').value),note=$('#editOldNotes').value.trim();if(!Number.isFinite(v)||v<=0)return toast('راجع القيمة');const before=entry.amountC;entry.amountC=cents(v);entry.note=note;entry.updatedAt=now();const tx=db.transaction(['historical','audit'],'readwrite');tx.objectStore('historical').put(entry);tx.objectStore('audit').add({id:uid('AU'),action:'historical_edit',reference:id,previousC:before,actualC:entry.amountC,actor:'cashier',createdAt:now()});await done(tx);closeModal();renderMore();toast('تم تعديل السجل التاريخي')};$('#cancelOldHistory').onclick=async()=>{if(!confirm('إلغاء القيد من إجمالي المبيعات القديمة مع الاحتفاظ به في سجل المراجعة؟'))return;entry.status='cancelled';entry.cancelledAt=now();const tx=db.transaction(['historical','audit'],'readwrite');tx.objectStore('historical').put(entry);tx.objectStore('audit').add({id:uid('AU'),action:'historical_cancel',reference:id,actor:'cashier',createdAt:now()});await done(tx);closeModal();renderMore();toast('تم إلغاء القيد مع حفظ أثر المراجعة')}}


$('#initialImport').onclick=async()=>{if((await all('products')).length)return toast('بيانات الأصناف موجودة بالفعل. استخدم Backup لنقل بياناتك بين الموبايلات.');$('#initialFile').click()};
$('#initialFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{const incoming=JSON.parse(await file.text());if(incoming?.app!=='sedra_pos_v5_initial_import'||incoming.schema!==1||!Array.isArray(incoming.products)||!incoming.products.length)throw Error('الملف مش ملف الجرد الافتتاحي المعتمد');const ps=await all('products'),[invoices,stock,history]=await Promise.all(['invoices','stock','historical'].map(all));if(ps.length||invoices.length||history.length||stock.some(x=>x.type!=='opening'))throw Error('لا يمكن استيراد الجرد الافتتاحي فوق بيانات موجودة');const ids=new Set(),bars=new Set(),codes=new Set();for(const p of incoming.products){if(!p.id||!p.name||!Number.isInteger(p.priceC)||p.priceC<=0||!Number.isFinite(p.stockQty)||!['weight','count'].includes(p.kind)||ids.has(p.id)||codes.has(p.code)||(p.barcode&&bars.has(p.barcode)))throw Error('فيه صنف غير صالح أو باركود مكرر في ملف الجرد');ids.add(p.id);codes.add(p.code);if(p.barcode)bars.add(p.barcode)}if(!confirm(`سيتم نقل ${incoming.products.length} صنف من ملف جرد سدرة إلى هذا الموبايل فقط، مع رصيد البداية.
تأكد إنك بتعمل ده أول مرة قبل التسجيل. موافق؟`))return;const at=now(),tx=db.transaction(['products','stock','settings','audit'],'readwrite');for(const raw of incoming.products){const p=normalizeProduct(raw);tx.objectStore('products').add(p);if(p.active)tx.objectStore('stock').add({id:uid('ST'),productId:p.id,qtyBase:p.stockQty,previous:null,actual:p.stockQty,type:'opening',reference:incoming.source,createdAt:at,dateKey:day()})}tx.objectStore('settings').put({key:'initialImportDone',value:at});tx.objectStore('settings').put({key:'openingSource',value:incoming.source});tx.objectStore('audit').add({id:uid('AU'),action:'opening_inventory_import',reference:incoming.source,count:incoming.products.length,actor:'cashier',createdAt:at});await done(tx);toast('تم استيراد الجرد الافتتاحي بالكامل');renderMore();renderProducts();refreshSaleWarnings()}catch(err){console.error(err);toast(err.message||'تعذر استيراد الجرد') }};

init();
